tile.clickEventHandler:
ESS.network.sendRequest(`/api/functions/IsLineManager`)
.then(function (isLineManager) {
  if (isLineManager) {
    ESS.actions.facilityActions.runFacility({ id: 'e80bb0fa-98fd-4420-ae32-d25ad3f20083'});
  }
  else {
    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.FACILITIES_RECALLVACATIONEMPLOYEE_WARNING'), ESS.L('@HRPROVACATIONS.FACILITIES_NNRECALLVACATIONEMPLOYEE_ISLINEMANAGER_ERROR'));
  }
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
});
